    Bug 1905844 - Work around a test not recording coverage data. r=aleca

    Also works around another potential issue with the test – not waiting for the right page to load before moving on.

    Differential Revision: https://phabricator.services.mozilla.com/D215474

diff --git a/mail/test/marionette/scripts/tabs.js b/mail/test/marionette/scripts/tabs.js
index 6d95de6210e..69f0e2f329b 100644
--- a/mail/test/marionette/scripts/tabs.js
+++ b/mail/test/marionette/scripts/tabs.js
@@ -18,14 +18,15 @@ for (const tab of tabmail.tabInfo) {
     continue;
   }
   if (tab.browser.isLoadingDocument) {
-    loadPromises.push(
-      new Promise(function (resolve) {
-        tab.browser.addEventListener("load", resolve, {
-          once: true,
-          capture: true,
-        });
-      })
-    );
+    const promise = Promise.withResolvers();
+    loadPromises.push(promise.promise);
+    function listener(event) {
+      if (event.target.location != "about:blank") {
+        tab.browser.removeEventListener("load", listener, { capture: true });
+        promise.resolve();
+      }
+    }
+    tab.browser.addEventListener("load", listener, { capture: true });
   }
 }

